@lkts I think the issue is that we don't discard the ignoredValues loader when another loader with the same name exists. This causes the undiscarded loaders to be used for the next document. This change should fix the issue. However, since you're on top of the synthetic source issue, please correct me if I missed anything.

```diff
diff --git a/server/src/main/java/org/elasticsearch/index/mapper/ObjectMapper.java b/server/src/main/java/org/elasticsearch/index/mapper/ObjectMapper.java
index 29ec0357d7c..297f5921874 100644
--- a/server/src/main/java/org/elasticsearch/index/mapper/ObjectMapper.java
+++ b/server/src/main/java/org/elasticsearch/index/mapper/ObjectMapper.java
@@ -22,7 +22,9 @@ import org.elasticsearch.index.IndexVersions;
 import org.elasticsearch.index.mapper.MapperService.MergeReason;
 import org.elasticsearch.xcontent.ToXContent;
 import org.elasticsearch.xcontent.XContentBuilder;
+import org.elasticsearch.xcontent.json.JsonXContent;
 
+import java.io.ByteArrayOutputStream;
 import java.io.IOException;
 import java.util.ArrayList;
 import java.util.Arrays;
@@ -915,8 +917,16 @@ public class ObjectMapper extends Mapper {
                 }
                 for (SourceLoader.SyntheticFieldLoader field : fields) {
                     if (field.hasValue()) {
-                        // Skip if the field source is stored separately, to avoid double-printing.
-                        orderedFields.computeIfAbsent(field.fieldName(), k -> new FieldWriter.FieldLoader(field));
+                        // discard if the field source is stored separately, to avoid double-printing.
+                        if (orderedFields.containsKey(field.fieldName())) {
+                            try (var discardingBuilder = new XContentBuilder(JsonXContent.jsonXContent, new ByteArrayOutputStream())) {
+                                discardingBuilder.startObject();
+                                field.write(discardingBuilder); // TODO: maybe have an explicit `discard` method
+                                discardingBuilder.endObject();
+                            }
+                        } else {
+                            orderedFields.put(field.fieldName(), new FieldWriter.FieldLoader(field));
+                        }
                     }
                 }
````

